#!/usr/bin/env dotnet
// Find the earliest Friday the 13th in the proleptic Gregorian calendar (starting 0001-01-01)
// and count all Friday the 13ths in a full 400-year cycle.

// Earliest Friday the 13th
var date = new DateTime(1, 1, 13);
while (date.DayOfWeek != DayOfWeek.Friday)
    date = date.AddMonths(1);

Console.WriteLine($"Earliest Friday the 13th: {date:yyyy-MM-dd}");

// Count Friday the 13ths in a full 400-year cycle (years 1–400)
int count = 0;
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        if (new DateTime(year, month, 13).DayOfWeek == DayOfWeek.Friday)
            count++;
    }
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");

// Bonus: distribution by day of week for the 13th
var dayCount = new int[7];
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
        dayCount[(int)new DateTime(year, month, 13).DayOfWeek]++;
}

Console.WriteLine("\nDay-of-week distribution for the 13th (400-year cycle):");
foreach (DayOfWeek d in Enum.GetValues<DayOfWeek>())
    Console.WriteLine($"  {d,-9}: {dayCount[(int)d]}");
EOF
